import { useState, useCallback, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { Wifi, Download, Upload, Activity, Server } from 'lucide-react';
import { ResponsiveContainer, AreaChart, Area, XAxis, Tooltip } from 'recharts';
import './index.css';

function SpeedChecker() {
  const [download, setDownload] = useState(0);
  const [upload, setUpload] = useState(0);
  const [ping, setPing] = useState(0);
  const [testing, setTesting] = useState(false);
  const [history, setHistory] = useState([]);

  const [network, setNetwork] = useState({
    isp: 'Detecting...',
    server: 'Detecting...',
    location: 'Detecting...',
    ip: 'Detecting...',
  });

  const API_BASE = process.env.REACT_APP_API_URL || window.location.origin;

  const loadNetworkInfo = useCallback(async () => {
    try {
      const res = await fetch('https://ipwho.is/', { cache: 'no-store' });
      const data = await res.json();

      if (data?.success) {
        setNetwork({
          isp: data.connection?.isp || data.connection?.org || 'Unknown ISP',
          server: 'Nearest Test Server',
          location: `${data.city || ''}${data.city ? ', ' : ''}${data.country || ''}`,
          ip: data.ip || 'Hidden',
        });
      }
    } catch {
      setNetwork({
        isp: 'Unable to detect',
        server: 'Nearest Test Server',
        location: 'Unable to detect',
        ip: 'Hidden',
      });
    }
  }, []);

  useEffect(() => {
    loadNetworkInfo();
  }, [loadNetworkInfo]);

  const averageLastValues = (values) => {
    if (!values.length) return 0;

    const clean = values.filter((v) => Number.isFinite(v) && v > 0).slice(-8);

    if (!clean.length) return 0;

    const sum = clean.reduce((a, b) => a + b, 0);
    return sum / clean.length;
  };

  const runTest = useCallback(async () => {
    try {
      setTesting(true);
      setDownload(0);
      setUpload(0);
      setPing(0);
      setHistory([]);

      await loadNetworkInfo();

      // ================= PING =================
      const pingSamples = [];

      for (let i = 0; i < 5; i++) {
        const start = performance.now();

        await fetch(`${API_BASE}/api/ping?t=${Date.now()}-${i}`, {
          cache: 'no-store',
        });

        pingSamples.push(performance.now() - start);
      }

      const avgPing = pingSamples.reduce((a, b) => a + b, 0) / pingSamples.length;

      setPing(Math.round(avgPing));

      // ================= DOWNLOAD =================
      const DOWNLOAD_DURATION = 10000;
      const DOWNLOAD_SIZE = 20 * 1024 * 1024;
      const downloadSamples = [];

      let totalDownloadedBytes = 0;
      let lastTime = performance.now();
      let lastBytes = 0;
      const downloadStart = performance.now();

      while (performance.now() - downloadStart < DOWNLOAD_DURATION) {
        const res = await fetch(`${API_BASE}/api/download?size=${DOWNLOAD_SIZE}&t=${Date.now()}`, {
          cache: 'no-store',
        });

        if (!res.body) {
          throw new Error('Download stream not supported');
        }

        const reader = res.body.getReader();

        while (true) {
          const { value, done } = await reader.read();
          if (done) break;

          totalDownloadedBytes += value.byteLength;

          const now = performance.now();
          const deltaTime = (now - lastTime) / 1000;
          const deltaBytes = totalDownloadedBytes - lastBytes;

          if (deltaTime >= 0.5) {
            const instantMbps = (deltaBytes * 8) / deltaTime / 1_000_000;

            // Ignore first 1.5 sec warm-up
            if (now - downloadStart > 1500) {
              downloadSamples.push(instantMbps);
            }

            const stableSpeed = averageLastValues(downloadSamples);
            const rounded = Math.round(stableSpeed);

            if (rounded > 0) {
              setDownload(rounded);

              setHistory((prev) => [
                ...prev.slice(-25),
                {
                  time: prev.length + 1,
                  speed: rounded,
                },
              ]);
            }

            lastTime = now;
            lastBytes = totalDownloadedBytes;
          }

          if (performance.now() - downloadStart >= DOWNLOAD_DURATION) {
            break;
          }
        }
      }

      const finalDownload = Math.round(averageLastValues(downloadSamples));
      setDownload(finalDownload);

      // ================= UPLOAD =================
      const UPLOAD_DURATION = 8000;
      const UPLOAD_SIZE = 1024 * 1024;
      const uploadChunk = new Uint8Array(UPLOAD_SIZE);

      let totalUploadedBytes = 0;
      let uploadLastTime = performance.now();
      let uploadLastBytes = 0;
      const uploadStart = performance.now();
      const uploadSamples = [];

      while (performance.now() - uploadStart < UPLOAD_DURATION) {
        const requestStart = performance.now();

        await fetch(`${API_BASE}/api/upload?t=${Date.now()}`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/octet-stream',
          },
          body: uploadChunk,
          cache: 'no-store',
        });

        totalUploadedBytes += uploadChunk.byteLength;

        const now = performance.now();
        const deltaTime = (now - uploadLastTime) / 1000;
        const deltaBytes = totalUploadedBytes - uploadLastBytes;

        if (deltaTime >= 0.5 || now - requestStart > 0) {
          const instantMbps = (deltaBytes * 8) / deltaTime / 1_000_000;

          // Ignore first 1 sec warm-up
          if (now - uploadStart > 1000 && Number.isFinite(instantMbps)) {
            uploadSamples.push(instantMbps);
          }

          const stableUpload = averageLastValues(uploadSamples);
          const rounded = Math.round(stableUpload);

          if (rounded > 0) {
            setUpload(rounded);
          }

          uploadLastTime = now;
          uploadLastBytes = totalUploadedBytes;
        }
      }

      const finalUpload = Math.round(averageLastValues(uploadSamples));
      setUpload(finalUpload);
    } catch (err) {
      console.error(err);
      alert(err.message || 'Speed test failed');
    } finally {
      setTesting(false);
    }
  }, [API_BASE, loadNetworkInfo]);

  return (
    <div className="speed-page">
      <div className="speed-app">
        <header className="topbar">
          <h1 className="logo-text">⚡ SpeedChecker</h1>

          <button className="run-btn" onClick={runTest} disabled={testing}>
            {testing ? 'Testing...' : 'Start Test'}
          </button>
        </header>

        <main>
          <section className="hero-section">
            <div className="speed-value">{download.toFixed(1)}</div>
            <div className="speed-unit">Mbps</div>

            <div className={`neon-ring ${testing ? 'ring-active' : ''}`}>
              <div className="ring-inner">
                <Wifi size={34} />
                <span>{testing ? 'Running' : 'Ready'}</span>
              </div>
            </div>

            <p className="status-text">
              {testing
                ? 'Testing sustained internet speed...'
                : 'Click start to test your connection'}
            </p>
          </section>

          <section className="cards">
            <div className="card">
              <Download size={22} />
              <p>Download</p>
              <h3>{download} Mbps</h3>
            </div>

            <div className="card">
              <Upload size={22} />
              <p>Upload</p>
              <h3>{upload} Mbps</h3>
            </div>

            <div className="card">
              <Activity size={22} />
              <p>Ping</p>
              <h3>{ping} ms</h3>
            </div>

            <div className="card">
              <Server size={22} />
              <p>Status</p>
              <h3>{testing ? 'Running' : 'Stable'}</h3>
            </div>
          </section>

          <section className="graph-box">
            <h2>Live Speed Graph</h2>

            <ResponsiveContainer width="100%" height={250}>
              <AreaChart data={history}>
                <XAxis dataKey="time" hide />
                <Tooltip
                  contentStyle={{
                    background: '#050816',
                    border: '1px solid #00f7ff',
                    borderRadius: '12px',
                    color: '#fff',
                  }}
                />
                <Area
                  type="monotone"
                  dataKey="speed"
                  stroke="#00f7ff"
                  fill="rgba(0,247,255,0.2)"
                  strokeWidth={3}
                />
              </AreaChart>
            </ResponsiveContainer>
          </section>

          <section className="network-box">
            <h2>Network Details</h2>

            <div className="network-grid">
              <div>
                <span>ISP</span>
                <strong>{network.isp}</strong>
              </div>

              <div>
                <span>Server</span>
                <strong>{network.server}</strong>
              </div>

              <div>
                <span>Location</span>
                <strong>{network.location}</strong>
              </div>

              <div>
                <span>IP Address</span>
                <strong>{network.ip}</strong>
              </div>
            </div>
          </section>

          <section className="seo-box">
            <h2>How Fast Is Your Internet?</h2>
            <p>
              Test your download speed, upload speed, ping and network stability instantly with
              SpeedChecker.
            </p>
          </section>
        </main>

        <footer className="footer">
          <Link to="/privacy-policy">Privacy</Link>
          <Link to="/terms-of-service">Terms</Link>
          <Link to="/about-us">About</Link>
        </footer>
      </div>
    </div>
  );
}

export default SpeedChecker;
